import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { useMoods, useThoughts } from '../hooks/useStorage';

const MOOD_HUE = { 1:0, 2:20, 3:42, 4:160, 5:195 };

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const [expanded, setExpanded]    = useState(null);
  const isEmpty = moods.length===0 && thoughts.length===0;
  const maxTrap = Math.max(...Object.values(trapCounts), 1);

  if (isEmpty) return (
    <div style={{ minHeight:'100vh', background:'#f0ede8', paddingBottom:96, display:'flex', flexDirection:'column', position:'relative', overflow:'hidden' }}>
      <div style={{ padding:'22px 22px 0' }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)' }}>Historik</span>
      </div>
      <div style={{ flex:1, display:'flex', flexDirection:'column', justifyContent:'flex-end', padding:'0 20px 0' }}>
        <div style={{ fontSize:'clamp(52px,14vw,86px)', fontWeight:900, letterSpacing:'-0.055em', lineHeight:0.84, color:'#111010', textTransform:'uppercase', marginBottom:'-24px', position:'relative', zIndex:3 }}>
          TOM
        </div>
        <div style={{ position:'relative', zIndex:2 }}>
          <MeshSphere size={220} speed={0.3} distort={0.35} hue1={195} hue2={212} />
        </div>
        <div style={{ position:'relative', zIndex:3, marginTop:'-10px' }}>
          <div style={{ height:1, background:'rgba(17,16,16,0.08)', marginBottom:14 }} />
          <p style={{ fontSize:14, color:'rgba(17,16,16,0.42)', marginBottom:20, fontWeight:300 }}>Inga tankar eller incheckningar ännu.</p>
          <div style={{ display:'flex', gap:8 }}>
            <button onClick={()=>setPage('home')} style={{ flex:1, padding:'13px', borderRadius:100, background:'#111010', color:'#f0ede8', fontSize:13, fontWeight:600, border:'none' }}>Analysera en tanke</button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#f0ede8', paddingBottom:96, position:'relative' }}>
      {/* Header — poster style */}
      <div style={{ display:'flex', justifyContent:'space-between', padding:'22px 22px 0', position:'relative', zIndex:3 }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)' }}>Historik</span>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.14em', color:'rgba(17,16,16,0.25)', textTransform:'uppercase' }}>
          {streak > 0 ? `${streak} dgr` : '—'}
        </span>
      </div>

      {/* Big stat number — like "34 Videos" in the black UI reference */}
      <div style={{ padding:'14px 20px 0', position:'relative', zIndex:3 }}>
        <div style={{ fontSize:'clamp(64px,18vw,110px)', fontWeight:900, letterSpacing:'-0.06em', lineHeight:0.8, color:'#111010' }}>
          {thoughts.length}
        </div>
        <div style={{ fontSize:'clamp(14px,4vw,20px)', fontWeight:300, fontStyle:'italic', color:'rgba(17,16,16,0.3)', letterSpacing:'-0.02em', marginTop:4 }}>
          {thoughts.length === 1 ? 'analys' : 'analyser'}
        </div>
      </div>

      {/* Orb — overlaps the number */}
      <div style={{ position:'relative', zIndex:2, marginTop:'-40px', display:'flex', justifyContent:'flex-end', paddingRight:'8%', pointerEvents:'none' }}>
        <MeshSphere size={200} speed={0.28} distort={0.3} hue1={195} hue2={212} />
      </div>

      {/* Content */}
      <div style={{ padding:'0 20px', position:'relative', zIndex:3, marginTop:'-20px' }}>
        <div style={{ height:1, background:'rgba(17,16,16,0.08)', marginBottom:20 }} />

        {/* Mood strip */}
        {moods.length > 0 && (
          <div style={{ marginBottom:24 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(17,16,16,0.3)', marginBottom:12 }}>Humör</p>
            <div style={{ display:'flex', alignItems:'flex-end', gap:3, height:48 }}>
              {[...moods].reverse().map((m, i) => {
                const h = MOOD_HUE[m.score];
                return (
                  <div key={i} style={{ flex:1, height:'100%', display:'flex', flexDirection:'column', justifyContent:'flex-end', alignItems:'center', gap:2 }}>
                    <div style={{ width:'100%', minHeight:3, height:`${(m.score/5)*100}%`, borderRadius:'2px 2px 0 0', background:`hsla(${h},55%,52%,0.65)` }} />
                    <span style={{ fontFamily:'DM Mono,monospace', fontSize:5.5, color:'rgba(17,16,16,0.22)', whiteSpace:'nowrap' }}>
                      {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Trap freq */}
        {Object.keys(trapCounts).length > 0 && (
          <div style={{ marginBottom:24 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(17,16,16,0.3)', marginBottom:12 }}>Tankefällor</p>
            {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([label,count]) => (
              <div key={label} style={{ display:'flex', alignItems:'center', gap:10, marginBottom:8 }}>
                <span style={{ fontSize:12, color:'rgba(17,16,16,0.52)', flex:1, fontWeight:300 }}>{label}</span>
                <div style={{ width:64, height:2, background:'rgba(17,16,16,0.08)', borderRadius:1 }}>
                  <div style={{ height:'100%', borderRadius:1, background:'rgba(17,16,16,0.28)', width:`${(count/maxTrap)*100}%` }} />
                </div>
                <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(17,16,16,0.28)', width:14, textAlign:'right' }}>{count}</span>
              </div>
            ))}
          </div>
        )}

        {/* Thought log */}
        {thoughts.length > 0 && (
          <>
            <div style={{ height:1, background:'rgba(17,16,16,0.08)', marginBottom:14 }} />
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(17,16,16,0.3)', marginBottom:10 }}>Tankelog</p>
            {thoughts.map((th, i) => (
              <div key={th.id} style={{ marginBottom:3 }}>
                <button onClick={() => setExpanded(expanded===i?null:i)}
                  style={{ width:'100%', textAlign:'left', padding:'12px 14px', background:expanded===i?'rgba(17,16,16,0.06)':'rgba(17,16,16,0.03)', border:'1px solid rgba(17,16,16,0.07)', borderRadius:expanded===i?'12px 12px 0 0':12, transition:'all .2s', display:'flex', alignItems:'center', gap:10 }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:'flex', justifyContent:'space-between', marginBottom:3 }}>
                      <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(17,16,16,0.42)', textTransform:'uppercase', letterSpacing:'0.08em' }}>{th.trap_icon} {th.trap_label}</span>
                      <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(17,16,16,0.22)' }}>{new Date(th.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}</span>
                    </div>
                    <p style={{ fontSize:12, color:'rgba(17,16,16,0.38)', fontStyle:'italic', margin:0, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:expanded===i?'normal':'nowrap' }}>
                      "{th.user_text?.slice(0,80)}{th.user_text?.length>80&&expanded!==i?'...':''}"
                    </p>
                  </div>
                  <span style={{ fontSize:11, color:'rgba(17,16,16,0.2)', transform:expanded===i?'rotate(180deg)':'none', transition:'transform .25s', flexShrink:0 }}>↓</span>
                </button>
                {expanded===i && (
                  <div style={{ padding:'12px 14px', background:'rgba(17,16,16,0.04)', border:'1px solid rgba(17,16,16,0.07)', borderTop:'none', borderRadius:'0 0 12px 12px', animation:'fadeUp .2s both' }}>
                    <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(17,16,16,0.3)', marginBottom:6 }}>Omramning</p>
                    <p style={{ fontSize:13, color:'rgba(17,16,16,0.65)', lineHeight:1.75, fontWeight:300 }}>{th.reframe}</p>
                  </div>
                )}
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
